/**
 * Which topics the examiners actually set, in the order worth revising.
 *
 * GENERATED by tools/pyq_frequency.py from her own past papers — do not edit by
 * hand; re-run the tool.
 *
 * Ranked by how many SITTINGS a topic appears in, then by question count. A
 * topic in all six sittings is one the board reliably asks about; a topic with
 * many questions in one sitting may just have been that paper's theme.
 *
 * This is evidence, not prophecy. It says what has been set, not what will be.
 * Nobody can predict the September paper and the app must never imply it can.
 *
 * Measured across 6 sittings: 2024-07-07, 2024-12-14, 2024-12-15, 2026-02-07, 2026-02-08, 2026-03-01
 */

export interface TopicPriority {
  id: string;
  name: string;
  strand: string;
  /** Questions seen on this topic across all sittings. */
  questions: number;
  /** How many of the sittings included it — the more reliable signal. */
  sittings: number;
}

