export const TOTAL_SITTINGS = 6;

/** Priority rank for a topic id; unranked topics sort last. */
export function rankOf(topicId: string | null | undefined): number {
  if (!topicId) return Number.MAX_SAFE_INTEGER;
  const i = TOPIC_PRIORITY.findIndex((t) => t.id === topicId);
  return i === -1 ? Number.MAX_SAFE_INTEGER : i;
}
